import { StyleSheet } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

/**
 * Creates compact-mode cell and text styles for the DataTable component.
 * Used when `size="compact"` to render denser rows with smaller font sizes.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createCompactStyles = (t: PdfcnTheme) => {
  const { spacing, fontWeights, lineHeights } = t.primitives;
  return StyleSheet.create({
    cell: {
      paddingHorizontal: spacing[2],
      paddingVertical: spacing[0.5],
    },
    footerText: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.primitives.typography.xs,
      fontWeight: fontWeights.semibold,
      lineHeight: lineHeights.normal,
    },
    headerText: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.primitives.typography.xs,
      fontWeight: fontWeights.semibold,
      lineHeight: lineHeights.normal,
    },
    text: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.primitives.typography.xs,
      lineHeight: lineHeights.normal,
    },
  });
};

/**
 * Converts an arbitrary cell value to a display string.
 * Returns an empty string for null/undefined values.
 * @param value - The raw cell value to format.
 */
export const formatValue = (value: unknown): string => {
  if (value === null || value === undefined) {
    return "";
  }
  if (typeof value === "number") {
    return String(value);
  }
  return String(value);
};

import { NgTemplateOutlet } from "@angular/common";
import {
  booleanAttribute,
  Component,
  computed,
  Directive,
  input,
  inject,
  Injector,
} from "@angular/core";

import {
  PdfTable,
  TABLE,
} from "@/components/pdf/table/table";
import { injectPdfcnTheme } from "@/components/pdf/theme-provider";
import { TakumiText } from "@/lib/pdf-primitives";
import type { Style } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

import { createCompactStyles, formatValue } from "./data-table.styles";
import type {
  DataTableColumn,
  DataTableProps,
  DataTableSize,
} from "./data-table.types";

/** Header, body, and footer cells with their text and compact styles. */
const dataTableLayout = <T extends Record<string, unknown>>(
  theme: PdfcnTheme,
  {
    columns,
    data,
    footer,
    size = "default",
  }: Pick<DataTableProps<T>, "columns" | "data" | "footer" | "size">
) => {
  const compact = createCompactStyles(theme);
  const isCompact = size === "compact";
  const alignStyle = (col: DataTableColumn<T>) =>
    col.align ? ({ textAlign: col.align } as Style) : {};

  return {
    footer:
      footer &&
      columns.map((col) => {
        const value = col.key in footer ? footer[col.key] : "";
        return {
          col,
          context: { $implicit: value },
          footer: !!value,
          text: formatValue(value),
          textStyle: isCompact
            ? [value ? compact.footerText : compact.text, alignStyle(col)]
            : undefined,
        };
      }),
    header: columns.map((col) => ({
      col,
      text: col.header,
      textStyle: isCompact ? [compact.headerText, alignStyle(col)] : undefined,
    })),
    isCompact,
    rows: data.map((row) =>
      columns.map((col) => {
        const value = row[col.key];
        return {
          col,
          context: { $implicit: value, row },
          text: formatValue(value),
          textStyle: isCompact ? [compact.text, alignStyle(col)] : undefined,
        };
      })
    ),
    styles: compact,
  };
};

/**
 * Matches the original pdfcn, where a per-row wrapper hides body rows
 * from `Table`: they keep the default variant and get no zebra stripes.
 */
@Directive({
  providers: [{ provide: PdfTable, useValue: null }],
  selector: "[pdfDataTableRowFragment]",
})
class DataTableRowFragment {}

/** Data table for PDF rendering with column definitions, footer support, and stripe options. */
@Component({
  imports: [DataTableRowFragment, TakumiText, NgTemplateOutlet, TABLE],
  selector: "pdf-data-table",
  template: `
    @let l = layout();
    @let cellStyle = l.isCompact ? l.styles.cell : undefined;
    <pdf-table
      [variant]="variant()"
      [zebraStripe]="stripe()"
      [noWrap]="noWrap()"
      [style]="style()"
    >
      <pdf-table-header>
        <pdf-table-row header>
          @for (cell of l.header; track cell.col.key) {
            <pdf-table-cell
              header
              [align]="cell.col.align ?? 'left'"
              [width]="cell.col.width"
              [style]="cellStyle"
              ><ng-container
                *ngTemplateOutlet="content; context: { $implicit: cell }"
            /></pdf-table-cell>
          }
        </pdf-table-row>
      </pdf-table-header>
      <pdf-table-body>
        @for (row of l.rows; track $index) {
          <pdf-table-row pdfDataTableRowFragment>
            @for (cell of row; track cell.col.key) {
              <pdf-table-cell
                [align]="cell.col.align ?? 'left'"
                [width]="cell.col.width"
                [style]="cellStyle"
                ><ng-container
                  *ngTemplateOutlet="
                    content;
                    context: { $implicit: cell, render: cell.col.render }
                  "
              /></pdf-table-cell>
            }
          </pdf-table-row>
        }
      </pdf-table-body>
      @if (l.footer; as footer) {
        <pdf-table-footer>
          <pdf-table-row footer>
            @for (cell of footer; track cell.col.key) {
              <pdf-table-cell
                [footer]="cell.footer"
                [align]="cell.col.align ?? 'left'"
                [width]="cell.col.width"
                [style]="cellStyle"
                ><ng-container
                  *ngTemplateOutlet="
                    content;
                    context: { $implicit: cell, render: cell.col.renderFooter }
                  "
              /></pdf-table-cell>
            }
          </pdf-table-row>
        </pdf-table-footer>
      }
    </pdf-table>
    <ng-template #content let-cell let-render="render">
      @if (render) {
        <ng-container
          *ngTemplateOutlet="render; context: cell.context; injector: injector"
        />
      } @else if (cell.textStyle) {
        <takumi-text [style]="cell.textStyle">{{ cell.text }}</takumi-text>
      } @else {
        <ng-container>{{ cell.text }}</ng-container>
      }
    </ng-template>
  `,
})
export class PdfDataTable<T extends Record<string, unknown>> {
  /** Templates passed in resolve the theme from where they render, not where they are declared. */
  protected readonly injector = inject(Injector);
  readonly columns = input.required<DataTableColumn<T>[]>();
  readonly data = input.required<T[]>();
  readonly variant = input<NonNullable<DataTableProps<T>["variant"]>>("grid");
  readonly footer = input<DataTableProps<T>["footer"]>();
  readonly stripe = input(false, { transform: booleanAttribute });
  readonly size = input<DataTableSize>("default");
  readonly noWrap = input(false, { transform: booleanAttribute });
  readonly style = input<DataTableProps<T>["style"]>();

  private readonly theme = injectPdfcnTheme();
  protected readonly layout = computed(() =>
    dataTableLayout(this.theme(), {
      columns: this.columns(),
      data: this.data(),
      footer: this.footer(),
      size: this.size(),
    })
  );
}

import type { TemplateRef } from "@angular/core";

import type { TableVariant } from "@/components/pdf/table/table.types";
import type { PDFComponentProps } from "@/types/pdf-components";

/** DataTable row density size. */
export type DataTableSize = "default" | "compact";

/** Template context of a `render` cell: the cell value and its row. */
export interface DataTableCellContext<T = Record<string, unknown>> {
  $implicit: unknown;
  row: T;
}

/** Template context of a `renderFooter` cell: the footer value. */
export interface DataTableFooterContext {
  $implicit: unknown;
}

/**
 * Column definition for a DataTable.
 * Props - `key` | `header` | `align` | `width` | `render` | `renderFooter`
 * @see {@link DataTableColumn}
 */
export interface DataTableColumn<T = Record<string, unknown>> {
  key: keyof T & string;
  header: string;
  align?: "left" | "center" | "right";
  width?: string | number;
  /**
   * Custom cell template. Must contain takumi-* primitives (`<takumi-text>`,
   * `<takumi-view>`, etc.), NOT HTML DOM elements.
   */
  render?: TemplateRef<DataTableCellContext<T>>;
  /**
   * Custom footer cell template. Same constraint: takumi-* primitives only.
   */
  renderFooter?: TemplateRef<DataTableFooterContext>;
}

/**
 * Data table for PDF rendering with column definitions, footer support, and stripe options.
 * Props - `columns` | `data` | `variant` | `footer` | `stripe` | `size` | `noWrap` | `style`
 * @see {@link DataTableProps}
 */
export interface DataTableProps<T = Record<string, unknown>> extends Omit<
  PDFComponentProps,
  "children"
> {
  columns: DataTableColumn<T>[];
  data: T[];
  /**
   * @default 'grid'
   */
  variant?: TableVariant;
  footer?: Partial<Record<keyof T & string, string | number>>;
  stripe?: boolean;
  /**
   * @default 'default'
   */
  size?: DataTableSize;
  noWrap?: boolean;
}
